import{_ as i,c as t,o,ae as a}from"./chunks/framework.DMK_uHmU.js";const h=JSON.parse('{"title":"User Profile Component Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-profile.md","filePath":"Administration/Manage/Users/user-profile.md"}'),n={name:"Administration/Manage/Users/user-profile.md"};function s(r,e,l,c,u,d){return o(),t("div",null,e[0]||(e[0]=[a('<h1 id="user-profile-component-guide" tabindex="-1">User Profile Component Guide <a class="header-anchor" href="#user-profile-component-guide" aria-label="Permalink to &quot;User Profile Component Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Profile component allows administrators to manage user account information, credentials, access levels, and security settings. This component is part of the overall user management system and provides a comprehensive interface for creating and modifying user profiles.</p><h2 id="accessing-the-user-profile-component" tabindex="-1">Accessing the User Profile Component <a class="header-anchor" href="#accessing-the-user-profile-component" aria-label="Permalink to &quot;Accessing the User Profile Component&quot;">​</a></h2><p>The User Profile component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the user profile page either by:</p><ul><li>Creating a new user: <code>/user/profile/new</code></li><li>Editing an existing user: <code>/user/profile/[user_id]</code></li></ul><h2 id="user-profile-interface-overview" tabindex="-1">User Profile Interface Overview <a class="header-anchor" href="#user-profile-interface-overview" aria-label="Permalink to &quot;User Profile Interface Overview&quot;">​</a></h2><p>The User Profile interface consists of these key components:</p><ol><li><strong>Header Section</strong>: Contains the component title &quot;User Profile&quot;, description, and action buttons</li><li><strong>Account Management Buttons</strong>: <ul><li>Enable/Disable User toggle</li><li>Password management button</li></ul></li><li><strong>User Information Form</strong>: Fields for entering and editing user information</li><li><strong>Form Sections</strong>: Logically organized sections for different types of user data</li></ol><h2 id="managing-user-information" tabindex="-1">Managing User Information <a class="header-anchor" href="#managing-user-information" aria-label="Permalink to &quot;Managing User Information&quot;">​</a></h2><h3 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h3><p>The top section of the form contains fields for essential user identity information:</p><ul><li><strong>First Name</strong> (Required): User&#39;s first name</li><li><strong>Last Name</strong> (Required): User&#39;s last name</li><li><strong>Employee ID</strong> (Optional): Organization-specific identifier</li><li><strong>Username</strong> (Required): System login name <ul><li>Must contain only lowercase letters and numbers</li><li>No spaces or special characters allowed</li><li>Length between 2-128 characters</li><li>Cannot be changed after user creation</li></ul></li><li><strong>Display Name</strong>: How the user appears in the system (auto-generated from first and last names)</li></ul><h3 id="employment-information" tabindex="-1">Employment Information <a class="header-anchor" href="#employment-information" aria-label="Permalink to &quot;Employment Information&quot;">​</a></h3><p>This section allows you to specify organizational details:</p><ul><li><strong>Job Role</strong>: Select from predefined roles (Manager, Developer, Executive, etc.)</li><li><strong>Description</strong>: Additional notes about the user or their position</li><li><strong>Organization</strong>: Tag-based field for assigning organizational units <ul><li>Multiple organizations can be added</li><li>New organizations can be created on-the-fly</li><li>Existing organizations appear as autocomplete suggestions</li></ul></li></ul><h3 id="platform-access-settings" tabindex="-1">Platform Access Settings <a class="header-anchor" href="#platform-access-settings" aria-label="Permalink to &quot;Platform Access Settings&quot;">​</a></h3><p>These settings control the user&#39;s access level and permissions:</p><ul><li><strong>Platform Access Level</strong> (Required): Determines base permissions <ul><li>User: Standard access</li><li>Manager: Departmental management capabilities</li><li>Content: Content creation and management access</li><li>Admin: Full system administration privileges</li></ul></li></ul><h3 id="token-allocation" tabindex="-1">Token Allocation <a class="header-anchor" href="#token-allocation" aria-label="Permalink to &quot;Token Allocation&quot;">​</a></h3><p>Control AI token usage for the user:</p><ul><li><strong>Allocated Tokens</strong>: Number of tokens (in thousands) allocated to the user <ul><li>Default: 300 (thousand)</li><li>Set to 0 for unlimited tokens</li></ul></li><li><strong>Hard Stop Token Count</strong>: Maximum token limit (in thousands) <ul><li>Default: 500 (thousand)</li><li>Set to 0 for no hard limit</li><li>When reached, the user cannot generate more tokens until reset</li></ul></li></ul><h3 id="contact-information" tabindex="-1">Contact Information <a class="header-anchor" href="#contact-information" aria-label="Permalink to &quot;Contact Information&quot;">​</a></h3><p>Essential contact details for system communications:</p><ul><li><strong>Mobile Phone</strong>: User&#39;s mobile number (format: +1 (###) ###-####)</li><li><strong>Multi-Factor Auth</strong>: Toggle to enable/disable SMS-based multi-factor authentication</li><li><strong>Email</strong> (Required): User&#39;s email address for system login and notifications</li></ul><h2 id="account-management-actions" tabindex="-1">Account Management Actions <a class="header-anchor" href="#account-management-actions" aria-label="Permalink to &quot;Account Management Actions&quot;">​</a></h2><h3 id="enabling-and-disabling-users" tabindex="-1">Enabling and Disabling Users <a class="header-anchor" href="#enabling-and-disabling-users" aria-label="Permalink to &quot;Enabling and Disabling Users&quot;">​</a></h3><p>To control whether a user can access the system:</p><ol><li>Click the &quot;Enable User&quot; or &quot;Disable User&quot; button in the top-right corner</li><li>A confirmation message will appear once the action completes</li><li>Disabled users cannot log in to the system but their account data is preserved</li></ol><h3 id="password-management" tabindex="-1">Password Management <a class="header-anchor" href="#password-management" aria-label="Permalink to &quot;Password Management&quot;">​</a></h3><p>The password management dialog provides options for handling user credentials:</p><ol><li><p>Click the &quot;Password&quot; button to open the password management dialog</p></li><li><p>Three options are available:</p><ul><li><p><strong>Force Password Reset</strong>:</p><ul><li>Invalidates the user&#39;s current password</li><li>Sends a verification code to the user&#39;s email or SMS</li><li>User must create a new password to regain access</li><li>Click &quot;Force Password Reset&quot; to initiate this process</li></ul></li><li><p><strong>Re-Invite User</strong>:</p><ul><li>For accounts locked due to inactivity (7-30 days after creation)</li><li>Sends a new invitation email with username and temporary password</li><li>Click &quot;Send Re-Invite&quot; to initiate this process</li></ul></li><li><p><strong>Self-Service Password Reset</strong>:</p><ul><li>Information about the standard &quot;Forgot Password&quot; process</li><li>No action required from administrators</li></ul></li></ul></li></ol><h3 id="re-inviting-users" tabindex="-1">Re-inviting Users <a class="header-anchor" href="#re-inviting-users" aria-label="Permalink to &quot;Re-inviting Users&quot;">​</a></h3><p>For users who haven&#39;t completed their account setup:</p><ol><li>Click the &quot;Password&quot; button to open the dialog</li><li>Select &quot;Send Re-Invite&quot;</li><li>An invitation with login credentials will be sent to the user&#39;s email</li></ol><h2 id="form-validation" tabindex="-1">Form Validation <a class="header-anchor" href="#form-validation" aria-label="Permalink to &quot;Form Validation&quot;">​</a></h2><p>The User Profile form includes validation to ensure data integrity:</p><ul><li><strong>Required Fields</strong>: First Name, Last Name, Username, Access Level, Email</li><li><strong>Username Format</strong>: Only lowercase letters and numbers, 2-128 characters</li><li><strong>Email Format</strong>: Must be a valid email address format</li></ul><p>Validation messages appear in real-time as you type, helping to quickly identify and correct issues.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Unable to enable/disable user</p><ul><li>Check your permissions (requires Admin role)</li><li>Ensure network connectivity to the user management service</li><li>Look for error messages in the toast notifications</li></ul><p><strong>Issue</strong>: Password reset email not received</p><ul><li>Verify the email address is correct</li><li>Check spam/junk folders</li><li>Ensure the email service is functioning properly</li></ul><p><strong>Issue</strong>: Re-invite not working</p><ul><li>Ensure the user has a valid email address</li><li>Check if the account is eligible for re-invitation</li><li>Review error messages for specific issues</li></ul><p><strong>Issue</strong>: Changes not saving</p><ul><li>Verify all required fields are completed</li><li>Check for validation errors (red text under fields)</li><li>Ensure you have appropriate permissions</li></ul><p><strong>Issue</strong>: &quot;Services Error&quot; message</p><ul><li>Note the error code provided in the message</li><li>Check network connectivity</li><li>Contact system administrator if the issue persists</li></ul><hr><p>For additional assistance with user profile management, please contact your system administrator.</p>',54)]))}const g=i(n,[["render",s]]);export{h as __pageData,g as default};
